from collections import deque
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
def f(I):
    H=len(I); W=len(I[0]); from collections import Counter
    bg=Counter(I[r][c] for r in range(H) for c in range(W)).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    q=deque()
    # border-connected bg cells
    for r in range(H):
        for c in (0,W-1):
            if I[r][c]==bg and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if I[r][c]==bg and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and I[nr][nc]==bg and not seen[nr][nc]:
                seen[nr][c]=True; q.append((nr,nc))
    O=[row[:] for row in I]
    for r in range(H):
        for c in range(W):
            if I[r][c]==bg and not seen[r][c]: O[r][c]=4
    return O
